const raw = $input.first().json;
const p = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const kinds = ['offer.reminder','bp.approval_requested','offer.delivery_escalated'];
if (!kinds.includes(p.event_type) || p.channel !== 'slack') throw new Error('INVALID_ALERT: event_type/channel');
for (const key of ['event_id','case_id','attempt_id','message']) {
  if (typeof p[key] !== 'string' || !p[key].trim() || p[key].length > 1500) throw new Error('INVALID_ALERT: '+key);
}
return [{json: {event_type:p.event_type, event_id:p.event_id, case_id:p.case_id,
  attempt_id:p.attempt_id, message:p.message, channel:'slack'}}];
